package edu.pe.cibertec.saibm.membresia.infrastructure.persistence;
import java.time.Instant; import java.util.UUID; import jakarta.persistence.*; import edu.pe.cibertec.saibm.membresia.domain.model.Plan;
@Entity @Table(name="membership_plans",uniqueConstraints=@UniqueConstraint(columnNames={"code","version"})) public class PlanJpaEntity {@Id UUID id;@Column(nullable=false)String code;@Column(nullable=false)String name;@Column(name="reservation_limit",nullable=false)int reservationLimit;@Column(nullable=false)int version;@Column(name="valid_from",nullable=false)Instant validFrom;Instant validUntil;boolean active;@Column(name="legacy_id")String legacyId;protected PlanJpaEntity(){}PlanJpaEntity(Plan p){id=p.id();code=p.code();name=p.name();reservationLimit=p.reservationLimit();version=p.version();validFrom=p.validFrom();validUntil=p.validUntil();active=p.active();legacyId=p.legacyId();}Plan domain(){return new Plan(id,code,name,reservationLimit,version,validFrom,validUntil,active,legacyId);}}
